311	type SmtpConfig = {
312	  host: string;
313	  port: number;
314	  user: string;
315	  pass: string;
316	  secure: boolean;
317	};
318	
319	/**
320	 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
321	 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
322	 * tolerance, the same env fallback. Loaded lazily so importing this module never
323	 * touches the DB (keeps the module unit-testable and side-effect-free).
324	 */
325	async function loadSmtpConfig(): Promise<SmtpConfig> {
326	  const { db } = await import("@/lib/db");
327	  const { decryptSecret } = await import("@/lib/crypto-box");
328	  const rows = await db.setting.findMany({
329	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
330	  });
331	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
332	  const storedPass = s.smtp_pass;
333	  const pass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
334	  return {
335	    host: s.smtp_host || process.env.SMTP_HOST || "",
336	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
337	    user: s.smtp_user || process.env.SMTP_USER || "",
338	    pass,
339	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
340	  };
341	}
342	
343	/**
344	 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
345	 * each message) rather than the platform's transactional `smtp_from`, so a cold
346	 * campaign always sends as its dedicated sending identity — never as the platform.
347	 */
348	export class NxeonSmtpTransport implements MailTransport {
349	  readonly name = "nxeon-smtp";
350	  constructor(private readonly cfg: SmtpConfig) {}
351	
352	  private transporter() {
353	    if (!this.cfg.host) {
354	      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
355	    }
356	    // Deliberately its own env var, NOT SMTP_TLS_SERVERNAME (that one belongs to
357	    // lib/mailer.ts's platform transactional relay, mail.nxeon.cloud). Cold email
358	    // connects to the isolated trynxeon.com relay by IP, so its cert's hostname is
359	    // different — sharing the platform's servername here made every cold-email
360	    // send fail TLS hostname verification the moment the relay got a real cert.
361	    const servername = process.env.COLDEMAIL_SMTP_TLS_SERVERNAME || undefined;
362	    return nodemailer.createTransport({
363	      host: this.cfg.host,
364	      port: this.cfg.port,
365	      secure: this.cfg.secure,
366	      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
367	      ...(servername ? { tls: { servername } } : {}),
368	    });
369	  }
370	
371	  async send(msg: RenderedMessage): Promise<SendResult> {
372	    const info = await this.transporter().sendMail({
373	      from: msg.from,
374	      to: msg.to,
375	      replyTo: msg.replyTo,
376	      subject: msg.subject,
377	      html: msg.html,
378	      text: msg.text,
379	      headers: msg.headers,
380	    });
381	    return { messageId: (info as { messageId?: string })?.messageId };
382	  }
383	}
384	
385	/**
386	 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
387	 * this phase must not add dependencies or send anything. When a brand's domain
388	 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
389	 * does not change.
390	 */
391	export class SesTransport implements MailTransport {
392	  readonly name = "ses";
393	  async send(_msg: RenderedMessage): Promise<SendResult> {
394	    throw new Error(
395	      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
396	        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
397	    );
398	  }
399	}
400	
401	export type TransportKind = "nxeon-smtp" | "ses";
402	
403	/**
404	 * Resolve the transport for a send. Defaults to Nxeon Mail SMTP. Async because
405	 * building the SMTP transport reads the Setting rows; kept off the module's import
406	 * path so tests can import the pure renderers without a DB.
407	 */
408	export async function getTransport(kind: TransportKind = "nxeon-smtp"): Promise<MailTransport> {
409	  if (kind === "ses") return new SesTransport();
410	  return new NxeonSmtpTransport(await loadSmtpConfig());
411	}
