153	/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
154	const MAX_SENDS_PER_SWEEP = 50;
155	/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
156	const THROTTLE_MIN_MS = 800;
157	const THROTTLE_MAX_MS = 2600;
158	
159	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
160	const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));
