191	function withinSendWindow(
192	  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
193	  now: Date,
194	): boolean {
195	  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
196	  const cur = minutesInTz(now, c.timezone || "UTC");
197	  const s = c.sendWindowStart;
198	  const e = c.sendWindowEnd;
199	  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
200	}
