212	/**
213	 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
214	 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
215	 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
216	 */
217	async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
218	  const steps = await db.sequenceStep.findMany({
219	    where: { campaignId: campaign.id },
220	    orderBy: { stepOrder: "asc" },
221	    select: { id: true, delayDays: true },
222	  });
223	  if (steps.length === 0) return;
224	
225	  const base = campaign.launchedAt ?? new Date();
226	  // Cumulative offset (days) at each step.
227	  let cumulative = 0;
228	  const stepSchedule = steps.map((s) => {
229	    cumulative += Math.max(0, s.delayDays);
230	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
231	  });
232	
233	  const members = await db.emailListMember.findMany({
234	    where: { listId: campaign.listId },
235	    select: { contactId: true, contact: { select: { email: true, emailStatus: true } } },
236	  });
237	  if (members.length === 0) return;
238	
239	  // LEAD-DB exclusion: never schedule a send for a non-mailable (dead / hard-bounced
240	  // / complained / unsubscribed) or globally/brand-suppressed contact. The send-time
241	  // suppression re-check remains as defence-in-depth for rows queued earlier.
242	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
243	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
244	    select: { email: true, domain: true, scope: true, brandId: true },
245	  });
246	
247	  // No documented lawful basis, no send. ConsentRecord is written by the import
248	  // flow; nothing structurally prevented a future contact-creation path from
249	  // producing sendable rows with zero consent evidence, so this is a hard gate,
250	  // not just a reporting count.
251	  const consented = new Set(
252	    (
253	      await db.consentRecord.findMany({
254	        where: { contactId: { in: members.map((m) => m.contactId) } },
255	        select: { contactId: true },
256	      })
257	    ).map((c) => c.contactId),
258	  );
259	
260	  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
261	  for (const m of members) {
262	    if (!isMailableStatus(m.contact?.emailStatus)) continue;
263	    if (m.contact?.email && isSuppressed(m.contact.email, campaign.brandId, suppressions)) continue;
264	    if (!consented.has(m.contactId)) continue;
265	    for (const s of stepSchedule) {
266	      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
267	    }
268	  }
269	  if (rows.length === 0) return;
270	  // createMany + skipDuplicates: never double-queues a message across sweeps.
271	  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
272	}
