497	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
498	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
499	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
500	  if (remaining > 0) return;
501	  const any = await db.coldSend.count({ where: { campaignId } });
502	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
503	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
