506	/**
507	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
508	 * keeps everything below inert until a human enables sending on prod.
509	 */
510	export async function coldEmailSendSweep(): Promise<void> {
511	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
512	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
513	
514	  let campaigns: CampaignForSend[];
515	  try {
516	    campaigns = await db.coldCampaign.findMany({
517	      where: { status: "SENDING" },
518	      select: {
519	        id: true,
520	        brandId: true,
521	        listId: true,
522	        launchedAt: true,
523	        sendWindowStart: true,
524	        sendWindowEnd: true,
525	        timezone: true,
526	      },
527	    });
528	  } catch {
529	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
530	    return;
531	  }
532	  if (campaigns.length === 0) return;
533	
534	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
535	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
536	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
537	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
538	  const now = new Date();
539	
540	  let transport: MailTransport;
541	  try {
542	    transport = await getTransport("nxeon-smtp");
543	  } catch (err) {
544	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
545	    return;
546	  }
547	
548	  let budget = MAX_SENDS_PER_SWEEP;
549	  for (const campaign of campaigns) {
550	    if (budget <= 0) break;
551	
552	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
553	    if (!brand) continue;
554	
555	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
556	    const eligibility = evaluateSendEligibility(brand, protectedSet);
557	    if (!eligibility.eligible) {
558	      await logEvent("warn", "coldemail.send.brand_blocked", {
559	        campaignId: campaign.id,
560	        brandId: brand.id,
561	        reasons: eligibility.reasons,
562	      });
563	      continue;
564	    }
565	
566	    const identity: SendIdentity = {
567	      id: brand.id,
568	      name: brand.name,
569	      fromName: brand.fromName,
570	      fromEmail: brand.fromEmail,
571	      replyTo: brand.replyTo,
572	      sendingDomain: brand.sendingDomain,
573	      physicalPostalAddress: brand.physicalPostalAddress,
574	    };
575	
576	    try {
577	      await scheduleCampaignSends(campaign);
578	      const sent = await processDueSends(campaign, identity, {
579	        now,
580	        transport,
581	        ceiling,
582	        warmupEnabled,
583	        footerDisclosure,
584	        budget,
585	      });
586	      budget -= sent;
587	      await maybeCompleteCampaign(campaign.id);
588	    } catch (err) {
589	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
590	    }
591	  }
592	}
