39	type PollInbox = {
40	  id: string;
41	  email: string;
42	  imapHost: string;
43	  imapPort: number;
44	  imapUser: string;
45	  imapPassEnc: string;
46	  imapTls: boolean;
47	  lastImapUid: number;
48	};
