50	/** Cap on messages examined per inbox per sweep — keeps a first poll bounded. */
51	const MAX_MESSAGES_PER_INBOX = 200;
52	
53	/** The sweep entrypoint. Polls every credentialed inbox; isolates failures. */
54	export async function coldEmailInboxPoll(): Promise<void> {
55	  let inboxes: PollInbox[];
56	  try {
57	    inboxes = await db.inbox.findMany({
58	      where: { imapHost: { not: "" }, imapUser: { not: "" } },
59	      select: {
60	        id: true,
61	        email: true,
62	        imapHost: true,
63	        imapPort: true,
64	        imapUser: true,
65	        imapPassEnc: true,
66	        imapTls: true,
67	        lastImapUid: true,
68	      },
69	    });
70	  } catch {
71	    return; // tables not migrated on this env — behave like a no-op
72	  }
73	  if (inboxes.length === 0) return; // no credentialed inboxes — nothing connects
74	
75	  for (const ib of inboxes) {
76	    try {
77	      await pollOneInbox(ib);
78	    } catch (err) {
79	      await logEvent("error", "coldemail.inbox.poll", { inboxId: ib.id, message: String((err as Error)?.message ?? err) });
80	    }
81	  }
82	}
