84	async function pollOneInbox(ib: PollInbox): Promise<void> {
85	  const pass = decryptSecret(ib.imapPassEnc);
86	  if (!pass) return; // password absent or undecryptable — cannot connect, skip quietly
87	
88	  // imapHost is the mailbox's real internal IP (mail.nxeon.cloud's public DNS points
89	  // at the platform host, not Mailcow — connecting by hostname silently reaches the
90	  // wrong server). The cert is issued for the hostname, so TLS needs an explicit
91	  // servername override or certificate hostname verification fails against the IP.
92	  const client = new ImapFlow({
93	    host: ib.imapHost,
94	    port: ib.imapPort || 993,
95	    secure: ib.imapTls,
96	    auth: { user: ib.imapUser, pass },
97	    tls: { servername: "mail.nxeon.cloud" },
98	    logger: false,
99	    emitLogs: false,
100	  });
101	
102	  let maxUid = ib.lastImapUid;
103	  await client.connect();
104	  try {
105	    const lock = await client.getMailboxLock("INBOX");
106	    try {
107	      const startUid = ib.lastImapUid + 1;
108	      let seen = 0;
109	      // UID-based fetch: `${startUid}:*` returns everything above the bookmark. The
110	      // `X:*` IMAP quirk can echo the latest message even when none is newer, so we
111	      // re-check `uid > lastImapUid` per row.
112	      for await (const msg of client.fetch(`${startUid}:*`, { uid: true, source: true, envelope: true }, { uid: true })) {
113	        if (seen >= MAX_MESSAGES_PER_INBOX) break;
114	        seen++;
115	        const uid = msg.uid;
116	        if (!uid || uid <= ib.lastImapUid) continue;
117	        if (uid > maxUid) maxUid = uid;
118	        if (!msg.source) continue;
119	        try {
120	          await ingestMessage(ib, uid, await simpleParser(msg.source as Buffer));
121	        } catch (err) {
122	          await logEvent("error", "coldemail.inbox.ingest", { inboxId: ib.id, uid, message: String((err as Error)?.message ?? err) });
123	        }
124	      }
125	    } finally {
126	      lock.release();
127	    }
128	  } finally {
129	    await client.logout().catch(() => null);
130	  }
131	
132	  // Advance the bookmark + stamp the poll even when nothing matched, so we never
133	  // re-scan the same UIDs next sweep.
134	  await db.inbox
135	    .update({ where: { id: ib.id }, data: { lastImapUid: Math.max(maxUid, ib.lastImapUid), lastPolledAt: new Date() } })
136	    .catch(() => null);
137	}
