139	/**
140	 * Does this inbound message look like a bounce/NDR rather than a human reply? A
141	 * real bounce comes from mailer-daemon/postmaster (never a contact), or carries a
142	 * standard RFC 3464 delivery-status part. Deliberately does NOT pattern-match on
143	 * subject wording — see the comment inside for why that's a false-positive trap.
144	 */
145	export function looksLikeBounce(parsed: ParsedMail, fromAddr: string): boolean {
146	  // Sender identity and DSN structure are reliable signals; subject-text phrase
147	  // matching is NOT — a real, interested contact can easily write something like
148	  // "Re: delivery has failed for our shipment" and get silently misclassified as
149	  // a bounce (dropped, never halts their remaining queued sends). A genuine NDR
150	  // from any standards-compliant MTA always comes from mailer-daemon/postmaster
151	  // or carries a proper message/delivery-status part; there's no need to guess
152	  // from wording, and guessing is strictly worse than occasionally missing a
153	  // malformed one.
154	  if (/^(mailer-daemon|postmaster)@/i.test(fromAddr)) return true;
155	  if (parsed.attachments?.some((a) => /^message\/delivery-status$/i.test(a.contentType))) return true;
156	  return false;
157	}
158	
159	/**
160	 * Recover the bounced address + severity from a standard DSN (RFC 3464): the
161	 * message/delivery-status part carries `Final-Recipient: rfc822;<addr>` and
162	 * `Status: 5.x.x` (permanent) or `4.x.x` (transient). Falls back to scanning the
163	 * whole body for the same fields when a sending MTA didn't attach a proper part.
164	 */
165	export function parseDsnBounce(parsed: ParsedMail): { email: string; hard: boolean } | null {
166	  const dsnPart = parsed.attachments?.find((a) => /^message\/delivery-status$/i.test(a.contentType));
167	  const text = dsnPart ? dsnPart.content.toString("utf8") : (parsed.text ?? "");
168	
169	  const recipMatch = text.match(/Final-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/i);
170	  const email = normalizeEmail(recipMatch?.[1]);
171	  if (!email || !email.includes("@")) return null;
172	
173	  const statusMatch = text.match(/Status:\s*(\d)\.\d+\.\d+/i);
174	  const hard = statusMatch
175	    ? statusMatch[1] === "5"
176	    : !/\btry(?:ing)? again\b|\btemporar(?:y|ily)\b|\bmailbox (?:full|over quota)\b/i.test(text);
177	  return { email, hard };
178	}
