180	/** Turn one parsed inbound message into a Conversation + Message (+ side effects). */
181	async function ingestMessage(ib: PollInbox, uid: number, parsed: ParsedMail): Promise<void> {
182	  const fromAddr = normalizeEmail(parsed.from?.value?.[0]?.address ?? "");
183	  if (!fromAddr || !fromAddr.includes("@")) return;
184	  // Ignore our own sent copies that may live in this mailbox.
185	  if (fromAddr === normalizeEmail(ib.email)) return;
186	
187	  // A bounce/NDR is never a contact reply — it comes from mailer-daemon, not the
188	  // recipient — so it must be routed to the hygiene pipeline here, before the
189	  // "known contact" gate below, or it is silently dropped and never suppressed.
190	  if (looksLikeBounce(parsed, fromAddr)) {
191	    const bounce = parseDsnBounce(parsed);
192	    if (bounce) {
193	      await recordFeedback(bounce.email, bounce.hard ? "HARD_BOUNCE" : "SOFT_BOUNCE", {
194	        note: (parsed.subject ?? "").slice(0, 300),
195	      }).catch((err) => logEvent("error", "coldemail.inbox.bounce", { inboxId: ib.id, uid, message: String(err) }));
196	    } else {
197	      await logEvent("warn", "coldemail.inbox.bounce_unparsed", { inboxId: ib.id, uid, subject: parsed.subject ?? "" });
198	    }
199	    return;
200	  }
201	
202	  // Only capture replies from a KNOWN contact (a reply to our outreach).
203	  const contact = await db.contact.findUnique({ where: { email: fromAddr }, select: { id: true, fullName: true, stage: true } });
204	  if (!contact) return;
205	
206	  const messageId = normalizeMessageId(parsed.messageId) || `<imap-${ib.id}-${uid}@nxeon>`;
207	  // Idempotency: if we already stored this Message-ID in this inbox's thread, stop.
208	  const dupe = await db.message.findFirst({
209	    where: { messageId, conversation: { inboxId: ib.id } },
210	    select: { id: true },
211	  });
212	  if (dupe) return;
213	
214	  const subject = (parsed.subject ?? "").slice(0, 300);
215	  const bodyText = (parsed.text ?? "").trim();
216	  const bodyHtml = typeof parsed.html === "string" ? parsed.html : "";
217	  const inReplyTo = normalizeMessageId(parsed.inReplyTo);
218	  const references = Array.isArray(parsed.references)
219	    ? parsed.references.map(normalizeMessageId).join(" ")
220	    : normalizeMessageId(parsed.references as string | undefined);
221	  const receivedAt = parsed.date ?? new Date();
222	
223	  // ---- Match the originating send (threading first, recipient fallback) ----
224	  const contactSends = await db.coldSend.findMany({
225	    where: { contactId: contact.id, inboxId: ib.id },
226	    orderBy: { createdAt: "desc" },
227	    select: { id: true, messageId: true, campaignId: true },
228	  });
229	  const matchedSendId =
230	    matchColdSendId(inReplyTo, references, buildSentIndex(contactSends)) ?? (contactSends[0]?.id ?? null);
231	  const matchedCampaignId =
232	    contactSends.find((s) => s.id === matchedSendId)?.campaignId ?? contactSends[0]?.campaignId ?? null;
233	
234	  // ---- Upsert the conversation ----
235	  const convo = await db.conversation.upsert({
236	    where: { inboxId_contactId: { inboxId: ib.id, contactId: contact.id } },
237	    create: {
238	      inboxId: ib.id,
239	      contactId: contact.id,
240	      campaignId: matchedCampaignId,
241	      subject,
242	      status: "REPLIED",
243	      lastMessageAt: receivedAt,
244	      unread: true,
245	    },
246	    update: {
247	      lastMessageAt: receivedAt,
248	      unread: true,
249	      // Fill campaign if we now know it and didn't before.
250	      ...(matchedCampaignId ? { campaignId: matchedCampaignId } : {}),
251	    },
252	    select: { id: true, status: true },
253	  });
254	
255	  // ---- Append the inbound message ----
256	  await db.message.create({
257	    data: {
258	      conversationId: convo.id,
259	      direction: "INBOUND",
260	      fromAddr,
261	      toAddr: normalizeEmail(ib.email),
262	      subject,
263	      bodyText: bodyText.slice(0, 100_000),
264	      bodyHtml: bodyHtml.slice(0, 200_000),
265	      messageId,
266	      inReplyTo,
267	      references,
268	      coldSendId: matchedSendId,
269	      receivedAt,
270	    },
271	  });
272	
273	  // ---- Advance the contact to REPLIED (never downgrade a warmer stage) ----
274	  await db.contact.updateMany({
275	    where: { id: contact.id, stage: { in: ["NEW", "CONTACTED"] } },
276	    data: { stage: "REPLIED" },
277	  });
278	  // Stamp the first-reply time (engagement signal for the lead DB).
279	  await db.contact.updateMany({ where: { id: contact.id, repliedAt: null }, data: { repliedAt: receivedAt } }).catch(() => null);
280	
281	  // ---- HALT the contact's remaining queued sends (mail-side reply detection) ----
282	  await db.coldSend
283	    .updateMany({
284	      where: { contactId: contact.id, status: "QUEUED" },
285	      data: { status: "CANCELLED", error: "Halted: contact replied" },
286	    })
287	    .catch(() => null);
288	
289	  // ---- Analytics spine: REPLY event(s) ----
290	  if (matchedSendId) {
291	    await db.emailEvent.create({ data: { sendId: matchedSendId, type: "REPLY" } }).catch(() => null);
292	  }
293	  await db.deliverabilityEvent
294	    .create({
295	      data: {
296	        type: "REPLY",
297	        inboxId: ib.id,
298	        campaignId: matchedCampaignId,
299	        contactId: contact.id,
300	        sendId: matchedSendId,
301	        provider: "imap",
302	      },
303	    })
304	    .catch(() => null);
305	
306	  // ---- Classify (rules always; Claude only if a key exists) ----
307	  const cls = await classifyReply(subject, bodyText, {});
308	  const unsub = cls === "UNSUBSCRIBE" || isUnsubscribeRequest(`${subject}\n${bodyText}`);
309	
310	  const finalStatus = cls ? classToConversationStatus(cls) : convo.status === "OPEN" ? "REPLIED" : "REPLIED";
311	  await db.conversation.update({
312	    where: { id: convo.id },
313	    data: { status: finalStatus, category: cls ?? "" },
314	  });
315	
316	  // Stage advancement from the classification (don't clobber WON/MEETING_BOOKED).
317	  const stageAdvance = cls ? classToContactStage(cls) : null;
318	  if (stageAdvance) {
319	    await db.contact
320	      .updateMany({ where: { id: contact.id, stage: { notIn: ["WON", "MEETING_BOOKED"] } }, data: { stage: stageAdvance } })
321	      .catch(() => null);
322	  }
323	
324	  // ---- Unsubscribe → contact UNSUBSCRIBED (dead) + GLOBAL suppression (idempotent) ----
325	  if (unsub) {
326	    // Run the lead-DB hygiene pipeline: sets emailStatus=UNSUBSCRIBED + deadAt so
327	    // this contact is excluded from every future campaign, then suppress globally.
328	    await applyContactHygiene(contact.id, "UNSUBSCRIBE", "Unsubscribe reply").catch(() => null);
329	    const existing = await db.suppression.findFirst({ where: { email: fromAddr, scope: "GLOBAL" }, select: { id: true } });
330	    if (!existing) {
331	      await db.suppression.create({ data: { email: fromAddr, scope: "GLOBAL", reason: "UNSUBSCRIBE" } }).catch(() => null);
332	    }
333	    await db.emailEvent.create({ data: { sendId: matchedSendId ?? "", type: "UNSUBSCRIBE" } }).catch(() => null);
334	  }
335	
336	  // ---- Webhooks ----
337	  await fireWebhookForReply(convo.id, fromAddr, contact.fullName, matchedCampaignId, ib.email, finalStatus, bodyText, cls, unsub);
338	}
339	
340	/** Fan out the reply / interested / unsubscribe webhook events. Best-effort. */
341	async function fireWebhookForReply(
342	  conversationId: string,
343	  contactEmail: string,
344	  contactName: string | null | undefined,
345	  campaignId: string | null,
346	  inboxEmail: string,
347	  status: string,
348	  body: string,
349	  cls: ReplyClass | null,
350	  unsub: boolean,
351	): Promise<void> {
352	  const base = {
353	    conversationId,
354	    contactEmail,
355	    contactName: contactName ?? undefined,
356	    campaignId,
357	    inboxEmail,
358	    status,
359	    snippet: body.replace(/\s+/g, " ").trim().slice(0, 280),
360	    occurredAt: new Date().toISOString(),
361	  };
362	  await fireWebhooks("reply", base);
363	  if (cls === "INTERESTED") await fireWebhooks("interested", base);
364	  if (unsub) await fireWebhooks("unsubscribe", base);
365	}
