58	function hhmm(mins: number | null): string {
59	  if (mins == null) return "";
60	  const h = Math.floor(mins / 60);
61	  const m = mins % 60;
62	  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
