1	"use server";
2	
3	// Cold Email Engine — Master Inbox + webhook server actions (Overhaul Phase 1).
4	//
5	// Every action re-checks requireArea("platform"). The reply-send path is a normal
6	// 1:1 email to an EXISTING conversation (someone who already replied to us) sent
7	// from that inbox's own SMTP — it never touches the bulk queue, so it is allowed
8	// while the bulk kill-switch is OFF. Webhook signing secrets are stored ENCRYPTED.
9	
10	import { revalidatePath } from "next/cache";
11	import { db } from "@/lib/db";
12	import { requireArea } from "@/lib/rbac";
13	import { encryptSecret } from "@/lib/crypto-box";
14	import { logEvent } from "@/lib/log";
15	import { sendConversationReply } from "@/lib/coldemail/inbox-send";
16	import { WEBHOOK_EVENTS, testFireEndpoint, type WebhookEvent } from "@/lib/coldemail/webhooks";
17	
18	type ActionState = { error?: string; ok?: boolean };
19	
20	const INBOX_PATH = "/admin/coldemail/inbox";
21	
22	// ---------------------------------------------------------------------------
23	// Replies + conversation status
24	// ---------------------------------------------------------------------------
25	
26	/** Send a threaded reply from the conversation's inbox and log it. */
27	export async function sendReply(_prev: ActionState, formData: FormData): Promise<ActionState> {
28	  await requireArea("platform");
29	  const conversationId = String(formData.get("conversationId") ?? "").trim();
30	  const bodyMarkdown = String(formData.get("body") ?? "");
31	  const subjectOverride = String(formData.get("subject") ?? "").trim() || undefined;
32	  if (!conversationId) return { error: "Missing conversation." };
33	
34	  const res = await sendConversationReply({ conversationId, bodyMarkdown, subjectOverride });
35	  if (!res.ok) return { error: res.error };
36	  revalidatePath(INBOX_PATH);
37	  return { ok: true };
38	}
39	
40	/** Mark a conversation read / unread (drives the unibox badge). */
41	export async function setConversationRead(conversationId: string, unread: boolean): Promise<ActionState> {
42	  await requireArea("platform");
43	  await db.conversation.update({ where: { id: conversationId }, data: { unread } }).catch(() => null);
44	  revalidatePath(INBOX_PATH);
45	  return { ok: true };
46	}
47	
48	/**
49	 * Operator outcome control (mark interested / not-interested / meeting-booked /
50	 * closed / reopen). Advances the linked contact's pipeline stage to match so the
51	 * inbox and the pipeline never disagree.
52	 */
53	export type ConversationOutcome =
54	  | "INTERESTED"
55	  | "NOT_INTERESTED"
56	  | "MEETING_BOOKED"
57	  | "CLOSED"
58	  | "REOPEN";
59	
60	export async function setConversationOutcome(conversationId: string, outcome: ConversationOutcome): Promise<ActionState> {
61	  await requireArea("platform");
62	  const convo = await db.conversation.findUnique({ where: { id: conversationId }, select: { contactId: true } });
63	  if (!convo) return { error: "Conversation not found." };
64	
65	  // (conversation status, category, contact stage) for each outcome.
66	  const map: Record<
67	    ConversationOutcome,
68	    { status: "INTERESTED" | "NOT_INTERESTED" | "CLOSED" | "OPEN"; category: string; stage?: "INTERESTED" | "MEETING_BOOKED" | "LOST" }
69	  > = {
70	    INTERESTED: { status: "INTERESTED", category: "INTERESTED", stage: "INTERESTED" },
71	    NOT_INTERESTED: { status: "NOT_INTERESTED", category: "NOT_INTERESTED", stage: "LOST" },
72	    MEETING_BOOKED: { status: "INTERESTED", category: "MEETING_BOOKED", stage: "MEETING_BOOKED" },
73	    CLOSED: { status: "CLOSED", category: "" },
74	    REOPEN: { status: "OPEN", category: "" },
75	  };
76	  const m = map[outcome];
77	
78	  await db.conversation.update({ where: { id: conversationId }, data: { status: m.status, category: m.category, unread: false } });
79	  if (m.stage) {
80	    await db.contact.update({ where: { id: convo.contactId }, data: { stage: m.stage } }).catch(() => null);
81	  }
82	  await logEvent("info", "coldemail.conversation.outcome", { conversationId, outcome });
83	  revalidatePath(INBOX_PATH);
84	  return { ok: true };
85	}
86	
87	/** Manually trigger the IMAP poller (the unibox "Check for replies" button). */
88	export async function pollInboxesNow(): Promise<ActionState> {
89	  await requireArea("platform");
90	  try {
91	    const { coldEmailInboxPoll } = await import("@/worker/coldemail-inbox");
92	    await coldEmailInboxPoll();
93	  } catch (err) {
94	    await logEvent("error", "coldemail.inbox.manualPoll", { message: String((err as Error)?.message ?? err) });
95	    return { error: "Could not poll inboxes (are IMAP credentials configured?)." };
96	  }
97	  revalidatePath(INBOX_PATH);
98	  return { ok: true };
99	}
100	
101	// ---------------------------------------------------------------------------
102	// Webhook endpoints
103	// ---------------------------------------------------------------------------
104	
105	const WEBHOOKS_PATH = "/admin/coldemail/webhooks";
106	
107	/** Create or update a webhook endpoint. The signing secret is write-only + encrypted. */
108	export async function saveWebhookEndpoint(_prev: ActionState, formData: FormData): Promise<ActionState> {
109	  await requireArea("platform");
110	  const id = String(formData.get("id") ?? "").trim() || null;
111	  const url = String(formData.get("url") ?? "").trim();
112	  const secretRaw = String(formData.get("secret") ?? "");
113	  const active = formData.get("active") == null ? true : formData.get("active") === "on" || formData.get("active") === "true";
114	
115	  if (!/^https:\/\/.+/i.test(url)) return { error: "Enter an https:// endpoint URL." };
116	  const events = formData
117	    .getAll("events")
118	    .map((e) => String(e))
119	    .filter((e): e is WebhookEvent => (WEBHOOK_EVENTS as string[]).includes(e));
120	  if (events.length === 0) return { error: "Select at least one event to send." };
121	
122	  const secretData = secretRaw ? { secretEnc: encryptSecret(secretRaw) } : {};
123	  try {
124	    if (id) {
125	      await db.webhookEndpoint.update({ where: { id }, data: { url, events, active, ...secretData } });
126	    } else {
127	      await db.webhookEndpoint.create({ data: { url, events, active, ...secretData } });
128	    }
129	  } catch (err) {
130	    await logEvent("error", "coldemail.webhook.save", { message: String(err) });
131	    return { error: "Could not save the webhook endpoint." };
132	  }
133	  revalidatePath(WEBHOOKS_PATH);
134	  return { ok: true };
135	}
136	
137	export async function deleteWebhookEndpoint(id: string): Promise<ActionState> {
138	  await requireArea("platform");
139	  await db.webhookEndpoint.delete({ where: { id } }).catch(() => null);
140	  revalidatePath(WEBHOOKS_PATH);
141	  return { ok: true };
142	}
143	
144	/** Fire a synthetic test event at an endpoint and report the delivery result. */
145	export async function testWebhookEndpoint(id: string): Promise<ActionState> {
146	  await requireArea("platform");
147	  const res = await testFireEndpoint(id);
148	  revalidatePath(WEBHOOKS_PATH);
149	  return res.ok ? { ok: true, error: `Test delivered (HTTP ${res.status}).` } : { error: `Test failed: ${res.status}` };
150	}
